using System; using System.Collections.Generic; using System.Linq; using System.Text.Json; using System.Threading; using System.Threading.Tasks;
using Parcs.Agent.Runtime;

public static class Core {
    public static double F(double x) {
        return Math.Exp(-x / 4.0) * Math.Cos(x + 0.5 * Math.Sin(2.0 * x));
    }
    public static double Simpson(double a, double b, int n) {
        double h = (b - a) / n;
        double s = F(a) + F(b);
        for (int i = 1; i < n; i++) {
            double x = a + i * h;
            double v = F(x);
            s += ((i % 2) == 1) ? 4.0 * v : 2.0 * v;
        }
        return s * h / 3.0;
    }
}

public class SubResult { public int k { get; set; } public double a { get; set; } public double b { get; set; } public double value { get; set; } }
public class RedResult { public double I { get; set; } public List<double> parts { get; set; } }

public class Sub0 : IAgentComputation {
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct) {
        double a = 0.0, b = 4.0;
        double v = Core.Simpson(a, b, 10000);
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new SubResult { k = 0, a = a, b = b, value = v })));
    }
}

public class Sub1 : IAgentComputation {
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct) {
        double a = 4.0, b = 8.0;
        double v = Core.Simpson(a, b, 10000);
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new SubResult { k = 1, a = a, b = b, value = v })));
    }
}

public class Red : IAgentComputation {
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct) {
        double total = 0.0;
        var parts = new List<double>();
        for (int j = 0; j < 2; j++) {
            string s = null;
            object o = input.GetPreviousOutputs(j);
            if (o is string str) {
                s = str;
            } else if (o is System.Collections.IEnumerable en) {
                foreach (var it in en) {
                    if (it != null) { s = it as string ?? it.ToString(); break; }
                }
            }
            if (s == null) throw new Exception("missing parent output " + j);
            var r = JsonSerializer.Deserialize<SubResult>(s);
            total += r.value;
            parts.Add(r.value);
        }
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new RedResult { I = total, parts = parts })));
    }
}
